use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
# [cfg (feature = "nightly")] impl < 'a , Ty > TyAndLayout < 'a , Ty > { # [doc = " Returns `Homogeneous` if this layout is an aggregate containing fields of"] # [doc = " only a single type (e.g., `(u32, u32)`). Such aggregates are often"] # [doc = " special-cased in ABIs."] # [doc = ""] # [doc = " Note: We generally ignore 1-ZST fields when computing this value (see #56877)."] # [doc = ""] # [doc = " This is public so that it can be used in unit tests, but"] # [doc = " should generally only be relevant to the ABI details of"] # [doc = " specific targets."] pub fn homogeneous_aggregate < C > (& self , cx : & C) -> Result < HomogeneousAggregate , Heterogeneous > where Ty : TyAbiInterface < 'a , C > + Copy , { match self . backend_repr { BackendRepr :: Scalar (scalar) => { let kind = match scalar . primitive () { Primitive :: Int (..) | Primitive :: Pointer (_) => RegKind :: Integer , Primitive :: Float (_) => RegKind :: Float , } ; Ok (HomogeneousAggregate :: Homogeneous (Reg { kind , size : self . size })) } BackendRepr :: SimdVector { .. } => { assert ! (! self . is_zst ()) ; Ok (HomogeneousAggregate :: Homogeneous (Reg { kind : RegKind :: Vector , size : self . size , })) } BackendRepr :: ScalarPair (..) | BackendRepr :: Memory { sized : true } => { let from_fields_at = | layout : Self , start : Size | -> Result < (HomogeneousAggregate , Size) , Heterogeneous > { let is_union = match layout . fields { FieldsShape :: Primitive => { unreachable ! ("aggregates can't have `FieldsShape::Primitive`") } FieldsShape :: Array { count , .. } => { assert_eq ! (start , Size :: ZERO) ; let result = if count > 0 { layout . field (cx , 0) . homogeneous_aggregate (cx) ? } else { HomogeneousAggregate :: NoData } ; return Ok ((result , layout . size)) ; } FieldsShape :: Union (_) => true , FieldsShape :: Arbitrary { .. } => false , } ; let mut result = HomogeneousAggregate :: NoData ; let mut total = start ; for i in 0 .. layout . fields . count () { let field = layout . field (cx , i) ; if field . is_1zst () { continue ; } if ! is_union && total != layout . fields . offset (i) { return Err (Heterogeneous) ; } result = result . merge (field . homogeneous_aggregate (cx) ?) ? ; let size = field . size ; if is_union { total = total . max (size) ; } else { total += size ; } } Ok ((result , total)) } ; let (mut result , mut total) = from_fields_at (* self , Size :: ZERO) ? ; match & self . variants { Variants :: Single { .. } | Variants :: Empty => { } Variants :: Multiple { variants , .. } => { let variant_start = total ; for variant_idx in variants . indices () { let (variant_result , variant_total) = from_fields_at (self . for_variant (cx , variant_idx) , variant_start) ? ; result = result . merge (variant_result) ? ; total = total . max (variant_total) ; } } } if total != self . size { Err (Heterogeneous) } else { match result { HomogeneousAggregate :: Homogeneous (_) => { assert_ne ! (total , Size :: ZERO) ; } HomogeneousAggregate :: NoData => { assert_eq ! (total , Size :: ZERO) ; } } Ok (result) } } BackendRepr :: Memory { sized : false } => Err (Heterogeneous) , } } }
}